#!/usr/bin/env node
/**
 * quality-gate.mjs — MyMediaDB unified quality ratchet.
 *
 * Based on the standalone gate generated by boatman (github.com/rafaelvieiras/boatman):
 * it reuses the baseline schema, the CLI modes, the ratchet logic and the
 * render (human/Markdown). The difference is that this version is POLYGLOT and lives
 * at the ROOT of the monorepo: it collects Go metrics (run at the root) AND TypeScript
 * metrics (run in `web/`) into a single `baseline.json`.
 *
 * Unlike the original gate (which only READS report files already generated by
 * external steps), this gate RUNS the collectors itself in every mode.
 * That is why `--local` is self-contained: `pre-push` only has to call this script.
 *
 * Zero dependencies beyond the Node built-ins.
 *
 * Usage:
 *   node scripts/quality-gate.mjs                    # CI mode (Markdown output)
 *   node scripts/quality-gate.mjs --local            # human output (terminal)
 *   node scripts/quality-gate.mjs --generate-baseline# runs the collectors and writes baseline.json
 *   node scripts/quality-gate.mjs --local --fast     # diff filter + cheap collectors only
 *   node scripts/quality-gate.mjs --local --full     # ignores the diff filter, runs everything
 *
 * Diff filter: `--local`/CI only run the collectors of the side
 * (Go/Web) that the current diff actually touched (see getChangedFiles/classifyDiff
 * below); `--generate-baseline` and `--full` always ignore this filter.
 *
 * Robustness: OPTIONAL Go tools (golangci-lint, govulncheck, gocyclo) that are
 * not on the PATH make the metric SKIPPED (with a warning); they never break nor
 * block the gate. gofmt and `go test` come with Go; jscpd and npm come from web.
 * CI installs all three and VERIFIES them before the collector runs.
 *
 * Three outcomes, never confused (see FALHOU):
 *   number  → measured;
 *   null    → skipped ON PURPOSE (side untouched, --fast, other workflow) — not a verdict;
 *   'failed'→ TRIED and could not measure → BLOCKING, because "unknown" is not "fine".
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { execSync, spawn, spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const WEB = join(ROOT, 'web');
const REPORTS = join(ROOT, 'reports');

const BASELINE_PATH = join(ROOT, 'baseline.json');
const PROJECT = 'my-media-db';

const isFast          = process.argv.includes('--fast');
const isFull          = process.argv.includes('--full');
// --fast always prints in the human format (it is an interactive iteration mode),
// even when someone runs just `--fast` without an explicit `--local`.
const isLocal        = process.argv.includes('--local') || isFast;
const isGenBaseline  = process.argv.includes('--generate-baseline');
const isE2E          = process.argv.includes('--e2e');
const isCI           = !isLocal && !isGenBaseline;

// ─── Split mode (CI) ─────────────────────────────────────────────────────────
// The gate measures two independent sides (Go at the root, Web in web/). They ran
// one after the other in a single job, which cost the SUM of the two. In CI each
// side now runs in its OWN job, on its own runner, and a third job merges the two
// partial reports — so the wall time is the MAXIMUM, not the sum.
//
//   --side=go|web      measure only that side, write the partial report with --out
//   --out=<file>       write the partial metrics JSON (consumed by the merge job)
//   --report=a,b       MERGE mode: read the partials, compare with the baseline,
//                      print the combined table and exit by the blocking verdict
const sideFlag = process.argv.find((a) => a.startsWith('--side='));
const onlySide = sideFlag ? sideFlag.slice('--side='.length) : null;
if (onlySide !== null && onlySide !== 'go' && onlySide !== 'web') {
  console.error(`--side inválido: ${onlySide} (use go ou web)`);
  process.exit(2);
}
const outFlag = process.argv.find((a) => a.startsWith('--out='));
const outFile = outFlag ? outFlag.slice('--out='.length) : null;
const reportFlag = process.argv.find((a) => a.startsWith('--report='));
const reportFiles = reportFlag
  ? reportFlag.slice('--report='.length).split(',').map((s) => s.trim()).filter(Boolean)
  : null;

// ─── ANSI helpers (only with --local) ────────────────────────────────────────
const c = {
  reset:  isLocal ? '\x1b[0m'  : '',
  bold:   isLocal ? '\x1b[1m'  : '',
  dim:    isLocal ? '\x1b[2m'  : '',
  green:  isLocal ? '\x1b[32m' : '',
  yellow: isLocal ? '\x1b[33m' : '',
  red:    isLocal ? '\x1b[31m' : '',
  cyan:   isLocal ? '\x1b[36m' : '',
};

function log(msg)  { console.log(msg); }
function warn(msg) { console.warn(`${c.yellow}⚠  ${msg}${c.reset}`); }

// ─── Metric definitions ──────────────────────────────────────────────────────
/**
 * lowerIsBetter: true  → regression when current > baseline
 * lowerIsBetter: false → regression when current < baseline
 * blocking: true       → exits 1 on regression (worse than the baseline)
 * blocking: 'zero'     → exits 1 if current > 0 (it must stay 0)
 * blocking: false      → only warns
 * side: 'go' | 'web'   → just the grouping label in the report
 */
const METRIC_DEFS = {
  // --- Go (run at the root) ---
  go_coverage_lines:     { label: 'Go: cobertura de linhas', unit: '%',     side: 'go',  lowerIsBetter: false, blocking: true   },
  e2e_coverage_lines:    { label: 'Go: cobertura E2E (jornadas)', unit: '%',side: 'go',  lowerIsBetter: false, blocking: true   },
  go_gofmt_unformatted:  { label: 'Go: arquivos não-gofmt',  unit: 'arqs',  side: 'go',  lowerIsBetter: true,  blocking: 'zero' },
  go_lint_issues:        { label: 'Go: issues golangci-lint',unit: 'issues',side: 'go',  lowerIsBetter: true,  blocking: false  },
  go_vuln_high:          { label: 'Go: vulnerabilidades',    unit: 'vulns', side: 'go',  lowerIsBetter: true,  blocking: 'zero' },
  go_cyclo_violations:   { label: 'Go: funções > gocyclo 10',unit: 'funcs', side: 'go',  lowerIsBetter: true,  blocking: false  },
  // --- TypeScript / web (run in web/) ---
  web_coverage_lines:    { label: 'Web: cobertura de linhas',unit: '%',     side: 'web', lowerIsBetter: false, blocking: true   },
  web_typecheck_errors:  { label: 'Web: erros de type-check',unit: 'erros', side: 'web', lowerIsBetter: true,  blocking: 'zero' },
  web_duplicate_percent: { label: 'Web: duplicação',         unit: '%',     side: 'web', lowerIsBetter: true,  blocking: true   },
  web_lint_issues:       { label: 'Web: issues ESLint',      unit: 'issues',side: 'web', lowerIsBetter: true,  blocking: false  },
  web_audit_critical:    { label: 'Web: vulns critical',     unit: 'vulns', side: 'web', lowerIsBetter: true,  blocking: 'zero' },
  // --- Browser E2E (Layer 2) — read from the artifacts of `make e2e-cov` ---
  e2e_binary_coverage_lines: { label: 'E2E: cobertura do binário (navegador)', unit: '%', side: 'e2e', lowerIsBetter: false, blocking: true },
  e2e_front_coverage_lines:  { label: 'E2E: cobertura do front (navegador)',   unit: '%', side: 'e2e', lowerIsBetter: false, blocking: true },
};

// ─── Diff filter ─────────────────────────────────────────────────────────────
// "Gate infrastructure" files: any change to them forces a complete run of both
// sides, so there is never a blind spot where a change to the gate/CI escapes
// validation.
const GATE_INFRA_FILES = new Set([
  'scripts/quality-gate.mjs',
  'lefthook.yml',
  '.golangci.yml',
  'baseline.json',
  'Makefile',
]);
function isGateInfraFile(f) {
  return GATE_INFRA_FILES.has(f) || f.startsWith('.github/workflows/');
}

const GO_SIDE_RE  = /^(cmd\/|internal\/|go\.mod$|go\.sum$)/;
const WEB_SIDE_RE = /^web\//;

/**
 * Returns the list of changed files (`string[]`) or `null` when it was not
 * possible to determine the diff base safely. `null` is ALWAYS treated as
 * "run everything" by the caller — never the opposite.
 */
function getChangedFiles() {
  if (isCI) {
    const base = process.env.GATE_DIFF_BASE;
    if (!base) return null;
    const check = spawnSync('git', ['cat-file', '-e', base], { cwd: ROOT, stdio: 'ignore' });
    if (check.status !== 0) return null;
    const r = run(`git diff --name-only ${base}...HEAD`);
    if (r.code !== 0) return null;
    return r.stdout.split('\n').map((l) => l.trim()).filter(Boolean);
  }

  // Local: tries upstream → origin/master → origin/main, in this order. Diff
  // against the WORKING TREE (not only HEAD) on purpose: `make gate-fast`
  // is meant to be used DURING the implementation, before committing — if it
  // compared only commits, changes not yet committed (the usual case of
  // someone iterating) would stay invisible to the filter.
  const candidateBases = ['@{upstream}', 'origin/master', 'origin/main'];
  for (const ref of candidateBases) {
    const mb = run(`git merge-base HEAD "${ref}"`);
    if (mb.code !== 0 || !mb.stdout.trim()) continue;
    const mergeBase = mb.stdout.trim();
    const diff = run(`git diff --name-only ${mergeBase}`);
    if (diff.code === 0) {
      return diff.stdout.split('\n').map((l) => l.trim()).filter(Boolean);
    }
  }
  return null;
}

/**
 * Classifies the list of changed files into `{ touchesGo, touchesWeb }`.
 * `files === null` (undetermined base) always becomes `{ true, true }`.
 */
function classifyDiff(files) {
  if (files === null) return { touchesGo: true, touchesWeb: true };

  let touchesGo = false;
  let touchesWeb = false;

  for (const f of files) {
    if (isGateInfraFile(f)) { touchesGo = true; touchesWeb = true; break; }
  }
  if (!(touchesGo && touchesWeb)) {
    for (const f of files) {
      if (GO_SIDE_RE.test(f)) touchesGo = true;
      if (WEB_SIDE_RE.test(f)) touchesWeb = true;
    }
  }
  return { touchesGo, touchesWeb };
}

// ─── Execution helpers ───────────────────────────────────────────────────────
function commandExists(cmd) {
  // Single command as a string (no args array) to avoid Node's DEP0190 when
  // combining `shell: true` with arguments.
  const probe = process.platform === 'win32' ? `where ${cmd}` : `command -v ${cmd}`;
  const r = spawnSync(probe, { stdio: 'ignore', shell: true });
  return r.status === 0;
}

/**
 * Runs a command and returns { code, stdout, stderr }. Never throws: it captures
 * non-zero exit codes (several tools exit !=0 when they "find something").
 */
function run(cmd, opts = {}) {
  try {
    const stdout = execSync(cmd, {
      cwd: opts.cwd ?? ROOT,
      stdio: ['ignore', 'pipe', 'pipe'],
      encoding: 'utf8',
      shell: true,
      maxBuffer: 64 * 1024 * 1024,
      env: process.env,
    });
    return { code: 0, stdout, stderr: '' };
  } catch (e) {
    return {
      code: typeof e.status === 'number' ? e.status : 1,
      stdout: e.stdout ? e.stdout.toString() : '',
      stderr: e.stderr ? e.stderr.toString() : '',
    };
  }
}

// Same contract as run(), but does not block the event loop.
//
// The collectors of one side are INDEPENDENT: vitest does not read tsc's output,
// `go test ./...` does not read golangci-lint's report. Running them one after the
// other made the side cost the SUM of the collectors; started together, it costs
// the SLOWEST one (plus CPU contention, which is why this is measured and not
// assumed).
//
// `run()` stays synchronous for the few callers that are not collectors (git
// commands, the diff base) and for the sequential steps inside a collector
// (`go test` → `go tool cover` reads the profile the first one wrote).
function runAsync(cmd, opts = {}) {
  return new Promise((resolve) => {
    const child = spawn(cmd, {
      cwd: opts.cwd ?? ROOT,
      shell: true,
      stdio: ['ignore', 'pipe', 'pipe'],
      env: process.env,
    });
    const CAP = 64 * 1024 * 1024;
    let stdout = '';
    let stderr = '';
    let resolvido = false;
    const concluir = (r) => {
      if (!resolvido) { resolvido = true; resolve(r); }
    };
    child.stdout.on('data', (d) => { if (stdout.length < CAP) stdout += d.toString(); });
    child.stderr.on('data', (d) => { if (stderr.length < CAP) stderr += d.toString(); });
    child.on('error', (e) => concluir({ code: 1, stdout, stderr: `${stderr}\n${e?.message ?? e}` }));
    child.on('close', (code, signal) => concluir({ code: code ?? (signal ? 1 : 0), stdout, stderr }));
  });
}

function countNonEmptyLines(s) {
  return s.split('\n').filter((l) => l.trim() !== '').length;
}

// Full log on demand: when a collector fails to RUN (not "found issues" — it
// could not produce a result), it writes the complete stdout+stderr to
// reports/<key>-failure.log and shows only the last ~40 lines in the
// terminal/Markdown — the real `--- FAIL:` from go test/vitest usually goes to
// stdout, which used to be discarded silently.
function logFailure(key, stdout, stderr, message) {
  const combined = `${stdout ?? ''}\n${stderr ?? ''}`;
  mkdirSync(REPORTS, { recursive: true });
  const logPath = join(REPORTS, `${key}-failure.log`);
  writeFileSync(logPath, combined, 'utf8');
  const tail = combined.split('\n').slice(-40).join('\n').trim();
  warn(message);
  if (tail) warn(tail);
  warn(`Saída completa em: ${logPath}`);
}

// The third outcome of a collector, and the one that used to be invisible.
//
// `null` means "there was nothing to measure here" — the side was not touched by
// the diff, `--fast` excluded the collector, or the metric belongs to another
// workflow. That is a legitimate skip and must not block.
//
// FALHOU means "it ran and could not produce a number": the suite does not
// compile, the tool is there but writes no report, the JSON has an unexpected
// shape. Reporting that as `null` — which is what this script did — turned a
// broken unit suite into a GREEN gate with the metric shown as "pulada". The gate
// would then block only when a metric that happened to be measured got worse,
// which is not what a ratchet promises. FALHOU is BLOCKING.
const FALHOU = 'failed';
// Why a metric is in the blocking list: "got worse" or "could not be measured".
// The two need different words, because the fix is different.
const MOTIVO_NAO_MEDIDO = 'nao-medido';

// Records the failure (full output in reports/<key>-failure.log) and returns the
// sentinel. Every "could not measure" path goes through here.
function falhou(key, stdout, stderr, message) {
  logFailure(key, stdout, stderr, message);
  return FALHOU;
}

// ─── Go collectors (run at the root) ─────────────────────────────────────────

// Coverage: go test -coverprofile → go tool cover -func → total %.
// go test/gofmt always exist (they ship with Go). If the tests fail to
// compile/run, the metric becomes FALHOU (blocking) — it never crashes.
async function collectGoCoverage() {
  const profile = join(REPORTS, 'go-coverage.out');
  const t = await runAsync(`go test ./... -coverprofile="${profile}" -covermode=set`);
  if (t.code !== 0) {
    return falhou('go_coverage_lines', t.stdout, t.stderr, 'go test falhou — cobertura NÃO MEDIDA (bloqueante):');
  }
  if (!existsSync(profile)) {
    return falhou('go_coverage_lines', t.stdout, t.stderr, 'go test passou mas não gerou o perfil de cobertura — cobertura NÃO MEDIDA:');
  }
  const f = await runAsync(`go tool cover -func="${profile}"`);
  if (f.code !== 0) {
    return falhou('go_coverage_lines', f.stdout, f.stderr, 'go tool cover falhou — cobertura NÃO MEDIDA:');
  }
  const line = f.stdout.trim().split('\n').filter((l) => l.startsWith('total:')).pop();
  const m = line && line.match(/(\d+(?:\.\d+)?)%/);
  if (!m) return falhou('go_coverage_lines', f.stdout, f.stderr, 'go tool cover não imprimiu a linha "total:" — cobertura NÃO MEDIDA:');
  return parseFloat(m[1]);
}

// E2E coverage: how much of the APP code the Layer 1 JOURNEYS (internal/e2e)
// touch, measured with -coverpkg over the rest of internal/ MINUS the test
// infra (the e2e package itself and the fake provider, which would inflate the
// number). A metric SEPARATE from the unit one on purpose (journey × branch).
// It runs with -count=1 (the go test cache has masked a failure before). null
// when it skips (it never crashes).
async function collectE2ECoverage() {
  const listed = await runAsync('go list ./internal/...');
  if (listed.code !== 0) {
    return falhou('e2e_coverage_lines', listed.stdout, listed.stderr, 'go list falhou — cobertura E2E NÃO MEDIDA:');
  }
  const pkgs = listed.stdout
    .trim()
    .split('\n')
    .filter((p) => p && !p.endsWith('/internal/e2e') && !p.endsWith('/internal/provider/fake'));
  if (pkgs.length === 0) {
    return falhou('e2e_coverage_lines', listed.stdout, listed.stderr, 'nenhum pacote para -coverpkg — cobertura E2E NÃO MEDIDA:');
  }
  const profile = join(REPORTS, 'e2e-coverage.out');
  const t = await runAsync(
    `go test ./internal/e2e/... -coverpkg="${pkgs.join(',')}" -covermode=set -coverprofile="${profile}" -count=1`,
  );
  if (t.code !== 0) {
    return falhou('e2e_coverage_lines', t.stdout, t.stderr, 'go test das jornadas falhou — cobertura E2E NÃO MEDIDA (bloqueante):');
  }
  if (!existsSync(profile)) {
    return falhou('e2e_coverage_lines', t.stdout, t.stderr, 'go test das jornadas passou mas não gerou o perfil — cobertura E2E NÃO MEDIDA:');
  }
  const f = await runAsync(`go tool cover -func="${profile}"`);
  if (f.code !== 0) {
    return falhou('e2e_coverage_lines', f.stdout, f.stderr, 'go tool cover (e2e) falhou — cobertura E2E NÃO MEDIDA:');
  }
  const line = f.stdout.trim().split('\n').filter((l) => l.startsWith('total:')).pop();
  const m = line && line.match(/(\d+(?:\.\d+)?)%/);
  if (!m) return falhou('e2e_coverage_lines', f.stdout, f.stderr, 'go tool cover (e2e) não imprimiu "total:" — cobertura E2E NÃO MEDIDA:');
  return parseFloat(m[1]);
}

// gofmt -l: number of unformatted .go files. Always available.
async function collectGofmt() {
  // Restricted to the Go code directories so it does not walk node_modules.
  const r = await runAsync('gofmt -l cmd internal');
  // gofmt exits != 0 on a parse error, and it prints nothing to stdout in that
  // case — counting lines would report "0 files unformatted", i.e. perfect
  // formatting, for a file it could not even read.
  if (r.code !== 0) {
    return falhou('go_gofmt_unformatted', r.stdout, r.stderr, 'gofmt -l retornou erro — formatação NÃO MEDIDA (bloqueante):');
  }
  return countNonEmptyLines(r.stdout);
}

// golangci-lint (OPTIONAL): counts the Issues in the JSON. v2 uses --output.json.path.
async function collectGolangciLint() {
  if (!commandExists('golangci-lint')) {
    // Absent tool = skip BY DESIGN (it is optional; local machines may not have it).
    // CI installs it and verifies it in its own step, so where the verdict matters
    // this path cannot be taken.
    warn('golangci-lint não está no PATH — métrica "go_lint_issues" pulada (instale com: go install github.com/golangci/golangci-lint/v2/cmd/golangci-lint@latest)');
    return null;
  }
  const out = join(REPORTS, 'golangci.json');
  // We write the JSON to a file (not to stdout) because golangci-lint v2
  // also prints a human summary ("N issues.") to stdout, which would dirty the JSON.
  const r = await runAsync(`golangci-lint run --config .golangci.yml --output.json.path "${out}" ./...`);
  // exit 1 = found issues (expected); it is only a real failure if the file does
  // not exist.
  if (!existsSync(out)) {
    return falhou('go_lint_issues', r.stdout, r.stderr, 'golangci-lint rodou e não produziu relatório JSON — lint NÃO MEDIDO (bloqueante):');
  }
  try {
    const data = JSON.parse(readFileSync(out, 'utf8'));
    if (!Array.isArray(data.Issues)) {
      return falhou('go_lint_issues', r.stdout, r.stderr, 'relatório do golangci-lint sem o campo Issues — lint NÃO MEDIDO:');
    }
    return data.Issues.length;
  } catch (e) {
    return falhou('go_lint_issues', r.stdout, r.stderr, `não foi possível parsear o JSON do golangci-lint (${e.message}) — lint NÃO MEDIDO:`);
  }
}

// govulncheck (OPTIONAL): stream of JSON objects. We count distinct OSVs with
// at least one reachable "finding" (top frame with a function) — the same thing
// govulncheck reports as "your code is affected by N vulnerabilities".
async function collectGovulncheck() {
  if (!commandExists('govulncheck')) {
    warn('govulncheck não está no PATH — métrica "go_vuln_high" pulada (instale com: go install golang.org/x/vuln/cmd/govulncheck@latest)');
    return null;
  }
  const r = await runAsync('govulncheck -json ./...');
  if (r.code !== 0 && !r.stdout.trim()) {
    return falhou('go_vuln_high', r.stdout, r.stderr, 'govulncheck falhou sem saída — vulnerabilidades NÃO MEDIDAS (bloqueante):');
  }
  const affected = new Set();
  for (const obj of splitJsonStream(r.stdout)) {
    const f = obj.finding;
    if (!f || !Array.isArray(f.trace) || f.trace.length === 0) continue;
    const top = f.trace[0];
    // "reachable" = the top frame has a function (the code really calls it).
    if (top && top.function) affected.add(f.osv);
  }
  return affected.size;
}

// gocyclo (OPTIONAL): number of functions above the limit 10.
async function collectGocyclo() {
  if (!commandExists('gocyclo')) {
    warn('gocyclo não está no PATH — métrica "go_cyclo_violations" pulada (instale com: go install github.com/fzipp/gocyclo/cmd/gocyclo@latest)');
    return null;
  }
  const r = await runAsync('gocyclo -over 10 cmd internal');
  // gocyclo exits 1 when there are violations; the output (one line per function)
  // is what counts.
  return countNonEmptyLines(r.stdout);
}

// Splits a stream of concatenated JSON objects (like govulncheck's -json)
// into individual objects, matching { } braces at the top level.
function splitJsonStream(raw) {
  const out = [];
  let depth = 0, start = -1, inStr = false, esc = false;
  for (let i = 0; i < raw.length; i++) {
    const ch = raw[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') { if (depth === 0) start = i; depth++; }
    else if (ch === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        try { out.push(JSON.parse(raw.slice(start, i + 1))); } catch { /* ignores fragments */ }
        start = -1;
      }
    }
  }
  return out;
}

// ─── Web collectors (run in web/) ────────────────────────────────────────────

// jscpd over web/src → duplication percentage.
async function collectWebDuplication() {
  if (!existsSync(WEB)) { warn('web/ não encontrado — duplicação pulada'); return null; }
  const outDir = join(REPORTS, 'jscpd');
  mkdirSync(outDir, { recursive: true });
  // Runs in web/, points the output to reports/jscpd at the root.
  const r = await runAsync(`npx --yes jscpd src --reporters json --output "${outDir}" --silent`, { cwd: WEB });
  const reportPath = join(outDir, 'jscpd-report.json');
  if (!existsSync(reportPath)) {
    return falhou('web_duplicate_percent', r.stdout, r.stderr, 'jscpd rodou e não gerou relatório — duplicação NÃO MEDIDA (bloqueante):');
  }
  try {
    const data = JSON.parse(readFileSync(reportPath, 'utf8'));
    const pct = data?.statistics?.total?.percentage ?? 0;
    return parseFloat(Number(pct).toFixed(2));
  } catch (e) {
    return falhou('web_duplicate_percent', r.stdout, r.stderr, `não foi possível parsear o relatório do jscpd (${e.message}) — duplicação NÃO MEDIDA:`);
  }
}

// npm audit --json in web → number of "critical" vulnerabilities.
async function collectWebAuditCritical() {
  if (!existsSync(WEB)) { warn('web/ não encontrado — audit pulado'); return null; }
  const r = await runAsync('npm audit --json', { cwd: WEB });
  const raw = r.stdout.trim();
  if (!raw) {
    return falhou('web_audit_critical', r.stdout, r.stderr, 'npm audit não produziu saída — auditoria NÃO MEDIDA (bloqueante):');
  }
  try {
    const data = JSON.parse(raw);
    const vulns = data?.metadata?.vulnerabilities ?? data?.vulnerabilities ?? {};
    if (typeof vulns === 'object' && !Array.isArray(vulns)) {
      return vulns.critical ?? 0;
    }
    // Old format (advisories).
    let crit = 0;
    for (const adv of Object.values(data?.advisories ?? {})) {
      if (adv.severity === 'critical') crit++;
    }
    return crit;
  } catch (e) {
    return falhou('web_audit_critical', r.stdout, r.stderr, `não foi possível parsear o npm audit (${e.message}) — auditoria NÃO MEDIDA:`);
  }
}

// Web type-check (tsc -b): compiles the project (with project references) and counts
// the type errors. `--force` ignores the incremental cache to ALWAYS re-check (the
// gate cannot pass just because the .tsbuildinfo says "up to date"). exit 0 = zero
// errors; otherwise, it counts the occurrences of "error TSxxxx" in the output. Guards
// against regression of the generated shape (e.g.: outdated guard-test fixture),
// which vitest (esbuild, no type-check) and eslint do not catch.
async function collectWebTypecheck() {
  if (!existsSync(WEB)) { warn('web/ não encontrado — type-check pulado'); return null; }
  const r = await runAsync('npx --yes tsc -b --force', { cwd: WEB });
  if (r.code === 0) return 0;
  const saida = `${r.stdout}\n${r.stderr}`;
  const m = saida.match(/error TS\d+/g);
  if (!m) {
    // exited !=0 but without a recognizable "error TS": tsc itself could not run
    // (missing binary, bad tsconfig). That is a failed measurement, not zero errors.
    return falhou('web_typecheck_errors', r.stdout, r.stderr, 'tsc -b falhou sem erros TS reconhecíveis — type-check NÃO MEDIDO (bloqueante):');
  }
  return m.length;
}

// ESLint (flat config in web/): runs `eslint . -f json`, sums errors + warnings
// from all files. eslint exits 1 when it finds a problem — that is expected; it is
// only a real failure if the JSON cannot be read/parsed.
async function collectWebLint() {
  if (!existsSync(WEB)) { warn('web/ não encontrado — lint pulado'); return null; }
  const r = await runAsync('npx --yes eslint . -f json', { cwd: WEB });
  const raw = r.stdout.trim();
  if (!raw) {
    return falhou('web_lint_issues', r.stdout, r.stderr, 'eslint não produziu saída JSON — lint NÃO MEDIDO (bloqueante):');
  }
  try {
    const files = JSON.parse(raw);
    if (!Array.isArray(files)) {
      return falhou('web_lint_issues', r.stdout, r.stderr, 'saída do eslint não é um array — lint NÃO MEDIDO:');
    }
    let total = 0;
    for (const f of files) {
      total += (f.errorCount ?? 0) + (f.warningCount ?? 0);
    }
    return total;
  } catch (e) {
    return falhou('web_lint_issues', r.stdout, r.stderr, `não foi possível parsear o JSON do eslint (${e.message}) — lint NÃO MEDIDO:`);
  }
}

// Web coverage (vitest + v8): runs `npm run test:coverage` in web/, reads
// coverage/coverage-summary.json → total.lines.pct. If the file is not generated
// (or the tests fail to produce the summary), the metric is FALHOU (blocking).
async function collectWebCoverage() {
  if (!existsSync(WEB)) { warn('web/ não encontrado — cobertura pulada'); return null; }
  const r = await runAsync('npm run test:coverage', { cwd: WEB });
  const summary = join(WEB, 'coverage', 'coverage-summary.json');
  if (!existsSync(summary)) {
    return falhou('web_coverage_lines', r.stdout, r.stderr, 'vitest não gerou coverage-summary.json — cobertura web NÃO MEDIDA (bloqueante):');
  }
  try {
    const data = JSON.parse(readFileSync(summary, 'utf8'));
    const pct = data?.total?.lines?.pct;
    if (typeof pct !== 'number') {
      return falhou('web_coverage_lines', r.stdout, r.stderr, 'coverage-summary.json sem total.lines.pct — cobertura web NÃO MEDIDA:');
    }
    return pct;
  } catch (e) {
    return falhou('web_coverage_lines', r.stdout, r.stderr, `não foi possível parsear o coverage-summary.json (${e.message}) — cobertura web NÃO MEDIDA:`);
  }
}

// ─── E2E collectors (Layer 2) ────────────────────────────────────────────────
// Unlike every collector above: they NEVER run Playwright/the build themselves
// — they only read the two artifacts that `make e2e-cov` already left ready in
// e2e/.artifacts/. If the artifact does not exist (Playwright has not run yet),
// the same pattern as the other collectors: it warns and returns null (metric
// skipped).
const E2E_ARTIFACTS = join(ROOT, 'e2e', '.artifacts');

// Reads the textfmt profile that `coberturaBinario()` (e2e/global-teardown.ts)
// writes and extracts the aggregate total via `go tool cover -func`, like the Go
// collectors.
async function collectE2EBinaryCoverage() {
  const perfil = join(E2E_ARTIFACTS, 'e2e-binary-coverage.txt');
  if (!existsSync(perfil)) {
    warn('e2e/.artifacts/e2e-binary-coverage.txt não encontrado — rode `make e2e-cov` antes; métrica "e2e_binary_coverage_lines" pulada');
    return null;
  }
  const f = await runAsync(`go tool cover -func="${perfil}"`);
  if (f.code !== 0) {
    return falhou('e2e_binary_coverage_lines', f.stdout, f.stderr, 'go tool cover falhou sobre o perfil E2E — cobertura do binário NÃO MEDIDA:');
  }
  const line = f.stdout.trim().split('\n').filter((l) => l.startsWith('total:')).pop();
  const m = line && line.match(/(\d+(?:\.\d+)?)%/);
  if (!m) return falhou('e2e_binary_coverage_lines', f.stdout, f.stderr, 'go tool cover não imprimiu "total:" no perfil E2E — cobertura do binário NÃO MEDIDA:');
  return parseFloat(m[1]);
}

// Reads the `{ linesPct }` JSON that `coberturaFront()` (e2e/global-teardown.ts) writes
// from the monocart report.
async function collectE2EFrontCoverage() {
  const arquivo = join(E2E_ARTIFACTS, 'e2e-front-coverage.json');
  if (!existsSync(arquivo)) {
    warn('e2e/.artifacts/e2e-front-coverage.json não encontrado — rode `make e2e-cov` antes; métrica "e2e_front_coverage_lines" pulada');
    return null;
  }
  try {
    const data = JSON.parse(readFileSync(arquivo, 'utf8'));
    if (typeof data?.linesPct !== 'number') {
      return falhou('e2e_front_coverage_lines', '', '', 'e2e-front-coverage.json sem linesPct — cobertura do front NÃO MEDIDA:');
    }
    return data.linesPct;
  } catch (e) {
    return falhou('e2e_front_coverage_lines', '', '', `não foi possível parsear e2e-front-coverage.json (${e.message}) — cobertura do front NÃO MEDIDA:`);
  }
}

// Collector for each metric, indexed by the same key used in METRIC_DEFS —
// it allows iterating METRIC_DEFS and deciding what to run without a parallel list.
const COLLECTORS = {
  go_coverage_lines:     collectGoCoverage,
  e2e_coverage_lines:    collectE2ECoverage,
  go_gofmt_unformatted:  collectGofmt,
  go_lint_issues:        collectGolangciLint,
  go_vuln_high:          collectGovulncheck,
  go_cyclo_violations:   collectGocyclo,
  web_coverage_lines:    collectWebCoverage,
  web_typecheck_errors:  collectWebTypecheck,
  web_duplicate_percent: collectWebDuplication,
  web_lint_issues:       collectWebLint,
  web_audit_critical:    collectWebAuditCritical,
  e2e_binary_coverage_lines: collectE2EBinaryCoverage,
  e2e_front_coverage_lines:  collectE2EFrontCoverage,
};

// `--fast` mode: only the cheap collectors of each side.
const FAST_METRIC_KEYS = new Set([
  'go_coverage_lines',
  'go_gofmt_unformatted',
  'web_coverage_lines',
  'web_typecheck_errors',
]);

const SIDE_LABELS = { go: 'Go (raiz)', web: 'Web (web/)', e2e: 'E2E (navegador)' };
const SIDE_SKIP_REASONS = {
  go:  'Go pulado: sem mudanças em cmd/, internal/, go.mod ou go.sum neste diff.',
  web: 'Web pulado: sem mudanças em web/ neste diff.',
};

// ─── Unified collection ──────────────────────────────────────────────────────
// `touches` = { touchesGo, touchesWeb }. When a side was not touched, it SKIPS
// the collector calls for that side entirely (it does not run the command and
// leaves the metric null) — reusing the null handling that already exists in
// compareMetrics/printLocal/printMarkdown.
async function collectMetrics(touches = { touchesGo: true, touchesWeb: true }, opts = {}) {
  const { fast = false, side = null } = opts;
  mkdirSync(REPORTS, { recursive: true });
  const metrics = {};
  const touchedBySide = { go: touches.touchesGo, web: touches.touchesWeb, e2e: true };

  // --e2e mode: only reads the artifacts of the 'e2e' side (it does not run
  // Go/Web); outside this mode, behavior identical to before (['go','web']).
  // `side` is the CI split: one job per side, the other side stays null here and
  // is filled by the other job in the merge report.
  // In split mode the other side's keys are simply ABSENT from the partial report
  // (the merge job supplies them). They are NOT pre-filled with null: a null from
  // the other job would overwrite a real value, and 'side' is not enough to tell
  // which keys belong together (e2e_coverage_lines belongs to the go side, while
  // e2e_binary/front belong to the browser side).
  const sides = isE2E ? ['e2e'] : (side ? [side] : ['go', 'web']);

  for (const side of sides) {
    if (!touchedBySide[side]) {
      log(`${c.dim}${SIDE_SKIP_REASONS[side]}${c.reset}`);
      for (const [key, def] of Object.entries(METRIC_DEFS)) {
        if (def.side === side) metrics[key] = null;
      }
      continue;
    }
    log(`${c.dim}Coletando métricas ${SIDE_LABELS[side]} (em paralelo)...${c.reset}`);
    const tarefas = [];
    for (const [key, def] of Object.entries(METRIC_DEFS)) {
      if (def.side !== side) continue;
      if (fast && !FAST_METRIC_KEYS.has(key)) {
        metrics[key] = null;
        continue;
      }
      tarefas.push([key, COLLECTORS[key]]);
    }
    // Started together, collected together: the side costs its slowest collector.
    // The values are assigned AFTER all finish so the report order stays the
    // METRIC_DEFS order, never the completion order.
    // A collector that THROWS is a measurement that failed, not a crash of the gate:
    // one broken collector must not take the other five down with it.
    const resultados = await Promise.all(tarefas.map(async ([key, coletor]) => {
      try {
        return [key, await coletor()];
      } catch (e) {
        warn(`coletor de "${key}" lançou exceção (${e?.message ?? e}) — métrica NÃO MEDIDA`);
        return [key, FALHOU];
      }
    }));
    for (const [key, valor] of resultados) metrics[key] = valor;
  }

  return metrics;
}

// ─── Baseline generation ─────────────────────────────────────────────────────
async function generateBaseline() {
  log(`${c.bold}Gerando baseline de qualidade para ${PROJECT}...${c.reset}\n`);
  const novasMetricas = await collectMetrics();

  // Always merges on top of the existing baseline.json (if any) — never
  // overwrites from scratch. Needed because `--generate-baseline --e2e` only
  // collects the 'e2e' side; without the merge, it would zero the current
  // go_*/web_* keys.
  let anteriores = {};
  if (existsSync(BASELINE_PATH)) {
    try {
      const existing = JSON.parse(readFileSync(BASELINE_PATH, 'utf8'));
      anteriores = existing?.metrics ?? {};
    } catch (e) {
      warn('não foi possível ler o baseline.json existente (será tratado como vazio): ' + e.message);
    }
  }
  // Never write FALHOU into baseline.json: the baseline is the reference the
  // ratchet compares against, and a measurement that failed today says nothing
  // about the reference. Keep the previous value (and say so).
  const medidas = {};
  for (const [key, val] of Object.entries(novasMetricas)) {
    if (val === FALHOU) {
      warn(`métrica "${key}" não foi medida nesta rodada — mantendo o valor anterior no baseline`);
      continue;
    }
    medidas[key] = val;
  }
  const metrics = { ...anteriores, ...medidas };

  const baseline = {
    generatedAt: new Date().toISOString(),
    commit: (() => {
      const r = run('git rev-parse --short HEAD');
      return r.code === 0 ? r.stdout.trim() : 'unknown';
    })(),
    project: PROJECT,
    metrics,
  };

  writeFileSync(BASELINE_PATH, JSON.stringify(baseline, null, 2) + '\n', 'utf8');
  log(`\n${c.green}✔ Baseline gravado em baseline.json${c.reset}`);
  log(`${c.dim}Commite este arquivo para a catraca avançar ao longo do tempo.${c.reset}\n`);
  log('Métricas atuais:');
  for (const [key, val] of Object.entries(metrics)) {
    const def = METRIC_DEFS[key];
    const shown = val === null ? `${c.yellow}pulada${c.reset}` : `${c.cyan}${val}${c.reset} ${def?.unit ?? ''}`;
    log(`  ${def?.label ?? key}: ${shown}`);
  }
  log('');
}

// ─── Comparison (ratchet) ────────────────────────────────────────────────────
function compareMetrics(current, baseline) {
  const regressions = [];
  const improvements = [];
  const unchanged = [];

  for (const [key, def] of Object.entries(METRIC_DEFS)) {
    const cur = current[key] ?? null;
    const base = baseline[key] ?? null;

    // Tried and could not measure: blocking, and a DIFFERENT cause from "got worse".
    // The metric's own policy still decides — a warning-level metric stays a warning.
    if (cur === FALHOU) { regressions.push({ key, def, cur: FALHOU, base, motivo: MOTIVO_NAO_MEDIDO }); continue; }
    if (cur === null) { unchanged.push({ key, def, cur: 'N/A', base }); continue; }
    if (base === null) { unchanged.push({ key, def, cur, base: 'N/A' }); continue; }

    const curNum  = typeof cur  === 'number' ? cur  : parseFloat(cur);
    const baseNum = typeof base === 'number' ? base : parseFloat(base);
    if (isNaN(curNum) || isNaN(baseNum)) { unchanged.push({ key, def, cur, base }); continue; }

    // blocking 'zero' — current must be 0, regardless of the baseline.
    if (def.blocking === 'zero') {
      if (curNum > 0) regressions.push({ key, def, cur: curNum, base: baseNum });
      else unchanged.push({ key, def, cur: curNum, base: baseNum });
      continue;
    }

    const threshold = 0.1; // tolerates floating point difference
    const isRegression = def.lowerIsBetter
      ? curNum > baseNum + threshold
      : curNum < baseNum - threshold;
    const isImprovement = def.lowerIsBetter
      ? curNum < baseNum - threshold
      : curNum > baseNum + threshold;

    if (isRegression) regressions.push({ key, def, cur: curNum, base: baseNum });
    else if (isImprovement) improvements.push({ key, def, cur: curNum, base: baseNum });
    else unchanged.push({ key, def, cur: curNum, base: baseNum });
  }

  return { regressions, improvements, unchanged };
}

// ─── Formatting ──────────────────────────────────────────────────────────────
function fmtDelta(cur, base) {
  if (typeof cur !== 'number' || typeof base !== 'number') return '';
  const delta = cur - base;
  const sign = delta >= 0 ? '+' : '';
  const arrow = delta > 0 ? '↑' : (delta < 0 ? '↓' : '=');
  return `${sign}${delta.toFixed(2)} ${arrow}`;
}

// ─── Local output (terminal) ─────────────────────────────────────────────────
function printLocal(current, result) {
  const { regressions, improvements, unchanged } = result;
  log(`${c.bold}Quality Gate — ${PROJECT}${c.reset}\n`);

  // Current × baseline × delta table.
  log(`${c.bold}Métricas (atual × baseline × delta):${c.reset}`);
  const all = [...improvements, ...unchanged, ...regressions]
    .sort((a, b) => Object.keys(METRIC_DEFS).indexOf(a.key) - Object.keys(METRIC_DEFS).indexOf(b.key));
  for (const { key, def, cur, base } of all) {
    const delta = fmtDelta(cur, base);
    let tag = `${c.dim}─${c.reset}`;
    if (improvements.some((i) => i.key === key)) tag = `${c.green}✔${c.reset}`;
    else if (regressions.some((r) => r.key === key)) tag = def.blocking !== false ? `${c.red}✘${c.reset}` : `${c.yellow}⚠${c.reset}`;
    const curStr = cur === 'N/A'
      ? `${c.dim}pulada${c.reset}`
      : (cur === FALHOU ? `${c.red}não medido${c.reset}` : `${cur} ${def.unit}`);
    const baseStr = base === 'N/A' ? 'N/A' : `${base} ${def.unit}`;
    log(`  ${tag} ${def.label.padEnd(28)} ${String(curStr).padStart(6)}   base ${baseStr}   ${delta}`);
  }
  log('');

  const blocking = regressions.filter((r) => r.def.blocking !== false);
  const warnings = regressions.filter((r) => r.def.blocking === false);

  if (warnings.length > 0) {
    log(`${c.yellow}Avisos (não bloqueiam):${c.reset}`);
    for (const { key, def, cur, base, motivo } of warnings) {
      const texto = motivo === MOTIVO_NAO_MEDIDO
        ? `${c.yellow}não medido${c.reset} (veja reports/${key}-failure.log)`
        : `${cur} ${def.unit} (era ${base} ${def.unit}  ${fmtDelta(cur, base)})`;
      log(`  ${c.yellow}⚠${c.reset} ${def.label}: ${texto}`);
    }
    log('');
  }

  if (blocking.length > 0) {
    log(`${c.red}${c.bold}Regressões (BLOQUEANTES):${c.reset}`);
    for (const { key, def, cur, base, motivo } of blocking) {
      const causa = motivo === MOTIVO_NAO_MEDIDO
        ? `não foi possível medir — saída completa em reports/${key}-failure.log`
        : (def.blocking === 'zero' ? `deve ser 0 (achou ${cur})` : `piorou vs baseline ${base}`);
      const valor = motivo === MOTIVO_NAO_MEDIDO ? 'não medido' : `${cur} ${def.unit}`;
      log(`  ${c.red}✘${c.reset} ${def.label}: ${c.red}${valor}${c.reset} — ${causa}`);
    }
    log('');
    log(`${c.red}${c.bold}Quality gate FALHOU.${c.reset} Corrija as regressões acima e rode de novo:`);
    log(`  ${c.cyan}make gate-local${c.reset}\n`);
    return false;
  }

  log(`${c.green}${c.bold}Quality gate PASSOU.${c.reset}\n`);
  return true;
}

// ─── CI output (Markdown) ────────────────────────────────────────────────────
function printMarkdown(current, result) {
  const { regressions, improvements, unchanged } = result;
  const blocking = regressions.filter((r) => r.def.blocking !== false);
  const warnings = regressions.filter((r) => r.def.blocking === false);
  const passed = blocking.length === 0;
  const status = passed ? '✅ Quality Gate PASSOU' : '❌ Quality Gate FALHOU';

  const lines = [];
  lines.push(`## ${status}`);
  lines.push('');
  lines.push(`**Projeto:** \`${PROJECT}\``);
  lines.push(`**Gerado:** ${new Date().toISOString()}`);
  lines.push('');
  lines.push('### Métricas');
  lines.push('');
  lines.push('| Lado | Métrica | Atual | Baseline | Delta | Status |');
  lines.push('|------|---------|-------|----------|-------|--------|');

  const allRows = [...improvements, ...unchanged, ...regressions]
    .sort((a, b) => Object.keys(METRIC_DEFS).indexOf(a.key) - Object.keys(METRIC_DEFS).indexOf(b.key));
  for (const { key, def, cur, base } of allRows) {
    const delta = (typeof cur === 'number' && typeof base === 'number') ? fmtDelta(cur, base) : '—';
    let icon = '➡️';
    if (improvements.some((i) => i.key === key)) icon = '✅';
    else if (regressions.some((r) => r.key === key)) icon = def.blocking !== false ? '❌' : '⚠️';
    const curStr = cur === 'N/A'
      ? '_pulada_'
      : (cur === FALHOU ? '❓ _não medido_' : `${cur} ${def.unit}`);
    const baseStr = base === 'N/A' ? '—' : `${base} ${def.unit}`;
    lines.push(`| ${def.side} | ${def.label} | ${curStr} | ${baseStr} | ${delta} | ${icon} |`);
  }
  lines.push('');

  if (blocking.length > 0) {
    lines.push('### ❌ Regressões bloqueantes');
    lines.push('');
    for (const { key, def, cur, base, motivo } of blocking) {
      const causa = motivo === MOTIVO_NAO_MEDIDO
        ? `**não foi possível medir** — o coletor rodou e não produziu resultado (saída em \`reports/${key}-failure.log\`)`
        : (def.blocking === 'zero' ? `deve ser 0 (achou ${cur} ${def.unit})` : `${cur} ${def.unit} ← era ${base} ${def.unit}`);
      lines.push(`- **${def.label}**: ${causa}`);
    }
    lines.push('');
    lines.push('> Corrija antes de mesclar. Se os novos valores forem intencionais e melhores, rode `make baseline` e commite o `baseline.json`.');
    lines.push('');
  }

  if (warnings.length > 0) {
    lines.push('### ⚠️ Avisos (não bloqueiam)');
    lines.push('');
    for (const { key, def, cur, base, motivo } of warnings) {
      const texto = motivo === MOTIVO_NAO_MEDIDO
        ? `não medido (saída em \`reports/${key}-failure.log\`)`
        : `${cur} ${def.unit} (era ${base} ${def.unit})`;
      lines.push(`- **${def.label}**: ${texto}`);
    }
    lines.push('');
  }

  if (improvements.length > 0) {
    lines.push('### ✅ Melhorias detectadas');
    lines.push('');
    for (const { def, cur, base } of improvements) {
      lines.push(`- **${def.label}**: ${cur} ${def.unit} (era ${base} ${def.unit})`);
    }
    lines.push('');
    lines.push('> Rode `make baseline` para avançar a catraca com essas melhorias.');
    lines.push('');
  }

  lines.push('---');
  lines.push('*Catraca unificada Go + TS — MyMediaDB (base: boatman)*');

  const markdown = lines.join('\n');
  log(markdown);
  mkdirSync(REPORTS, { recursive: true });
  const reportFile = isE2E ? 'e2e-quality-gate-report.md' : 'quality-gate-report.md';
  writeFileSync(join(REPORTS, reportFile), markdown + '\n', 'utf8');
  return passed;
}

// ─── Merge of the two CI partial reports ─────────────────────────────────────
// The Go job and the Web job each measured ONE side and wrote a partial JSON. This
// runs in the final (cheap) job: it reuses the SAME comparison and the SAME Markdown
// renderer as a single-run gate, so the PR gets one table and one verdict — the split
// changes WHERE the work runs, never what the ratchet means.
function mergedReport(baseline) {
  const current = {};
  for (const file of reportFiles) {
    let partial;
    try {
      partial = JSON.parse(readFileSync(file, 'utf8'));
    } catch (e) {
      warn(`não foi possível ler o relatório parcial ${file}: ${e.message}`);
      process.exit(1);
    }
    Object.assign(current, partial.metrics ?? partial);
  }

  // A key ABSENT from a partial report is not a skip: a skip arrives as an explicit
  // null in the JSON (the side was not touched, or --fast excluded the collector).
  // Absent means the job never got to measure it — so it is FALHOU, and it blocks.
  // The two browser metrics belong to the E2E workflow, which merges its own pass —
  // their absence here is expected and is not a hole.
  const missing = Object.keys(METRIC_DEFS).filter((k) => !(k in current) && METRIC_DEFS[k].side !== 'e2e');
  if (missing.length > 0) {
    warn(`métricas ausentes nos relatórios parciais (tratadas como NÃO MEDIDAS): ${missing.join(', ')}`);
    for (const k of missing) current[k] = FALHOU;
  }

  return printMarkdown(current, compareMetrics(current, baseline));
}

// ─── Main ────────────────────────────────────────────────────────────────────
async function main() {
  if (isGenBaseline) { await generateBaseline(); return; }

  if (!existsSync(BASELINE_PATH)) {
    warn('baseline.json não encontrado. Rode: make baseline');
    warn('Pulando comparação da catraca.');
    process.exit(0);
  }

  let baseline;
  try {
    const raw = JSON.parse(readFileSync(BASELINE_PATH, 'utf8'));
    baseline = raw.metrics ?? raw;
  } catch (e) {
    warn('não foi possível ler baseline.json: ' + e.message);
    process.exit(1);
  }

  let touches;
  if (isFull) {
    touches = { touchesGo: true, touchesWeb: true };
    log(`${c.dim}--full: filtro por diff ignorado, rodando os dois lados completos.${c.reset}`);
  } else {
    const changed = getChangedFiles();
    touches = classifyDiff(changed);
    if (changed === null) {
      log(`${c.dim}Base do diff indeterminada — rodando os dois lados completos (fallback seguro).${c.reset}`);
    }
  }
  if (isFast) {
    warn('Modo --fast: só coletores baratos (go_coverage_lines, go_gofmt_unformatted, web_coverage_lines, web_typecheck_errors). Não substitui a rodada completa antes do push.');
  }

  if (reportFiles) {
    // Merge mode: the two sides were measured in their own jobs.
    if (!mergedReport(baseline)) process.exit(1);
    return;
  }

  const current = await collectMetrics(touches, { fast: isFast, side: onlySide });
  if (outFile) {
    // Partial report consumed by the merge job (see mergedReport).
    mkdirSync(dirname(outFile), { recursive: true });
    writeFileSync(outFile, JSON.stringify({ side: onlySide, metrics: current }, null, 2) + '\n', 'utf8');
    log(`${c.dim}métricas parciais em ${outFile}${c.reset}`);
  }
  const result  = compareMetrics(current, baseline);

  const passed = isLocal ? printLocal(current, result) : printMarkdown(current, result);
  if (!passed) process.exit(1);
}

await main();
